add("it3.q2", ("ग्लूकोज़ के ऑक्सीकरण से भिन्न जीवों में ऊर्जा प्राप्त करने के विभिन्न पथ क्या हैं?", "જુદા જુદા સજીવોમાં ગ્લુકોઝના ઑક્સિડેશનથી ઊર્જા મેળવવાના જુદા જુદા માર્ગો કયા છે?"),
    {0: ("सभी कोशिकाओं में ग्लूकोज़ पहले कोशिकाद्रव्य में पाइरुवेट में टूटता है।", "બધા કોષોમાં ગ્લુકોઝ પહેલાં કોષરસમાં પાયરુવેટમાં તૂટે છે."),
     1: ("ऑक्सीजन के बिना, यीस्ट में, पाइरुवेट से एथेनॉल और कार्बन डाइऑक्साइड बनते हैं; ऑक्सीजन की कमी में, हमारी पेशी कोशिकाओं में, लैक्टिक अम्ल बनता है।", "ઑક્સિજન વિના, યીસ્ટમાં, પાયરુવેટમાંથી ઇથેનૉલ અને કાર્બન ડાયૉક્સાઇડ બને છે; ઑક્સિજનની ઊણપમાં, આપણા સ્નાયુકોષોમાં, લેક્ટિક ઍસિડ બને છે."),
     2: ("ऑक्सीजन के साथ, माइटोकॉन्ड्रिया में, पाइरुवेट कार्बन डाइऑक्साइड और जल में टूटता है, जिससे कहीं अधिक ऊर्जा मुक्त होती है।", "ઑક્સિજન સાથે, કણાભસૂત્રમાં, પાયરુવેટ કાર્બન ડાયૉક્સાઇડ અને પાણીમાં તૂટે છે, જેથી ઘણી વધુ ઊર્જા મુક્ત થાય છે.")})
add("it3.q3", ("मनुष्यों में ऑक्सीजन तथा कार्बन डाइऑक्साइड का परिवहन कैसे होता है?", "મનુષ્યમાં ઑક્સિજન અને કાર્બન ડાયૉક્સાઇડનું વહન કેવી રીતે થાય છે?"),
    {0: ("ऑक्सीजन को लाल रुधिर कणिकाओं का लाल वर्णक हीमोग्लोबिन फुफ्फुसों से ऊतकों तक ले जाता है।", "ઑક્સિજનને રક્તકણોનું લાલ રંજકદ્રવ્ય હિમોગ્લોબિન ફેફસાંમાંથી પેશીઓ સુધી લઈ જાય છે."),
     1: ("कार्बन डाइऑक्साइड जल में अधिक विलेय है, इसलिए यह अधिकतर प्लैज्मा में घुलकर ऊतकों से फुफ्फुसों तक जाती है।", "કાર્બન ડાયૉક્સાઇડ પાણીમાં વધુ દ્રાવ્ય છે, તેથી તે મોટે ભાગે રુધિરરસમાં ઓગળીને પેશીઓમાંથી ફેફસાં સુધી જાય છે.")})
add("it3.q4", ("गैसों के विनिमय के लिए मानव फुफ्फुस में अधिकतम क्षेत्रफल को कैसे अभिकल्पित किया गया है?", "વાયુઓની આપ-લે માટે મહત્તમ ક્ષેત્રફળ મળે તે રીતે માનવ ફેફસાં કેવી રીતે રચાયેલાં છે?"),
    {0: ("श्वसनिकाएँ लाखों गुब्बारे जैसी कूपिकाओं में समाप्त होती हैं; फैलाने पर उनकी सतह लगभग 80 m² होगी।", "શ્વસનિકાઓ લાખો ફુગ્ગા જેવા વાયુકોષ્ઠોમાં પૂરી થાય છે; ફેલાવીએ તો તેમની સપાટી આશરે 80 m² થાય."),
     1: ("कूपिकाओं की भित्ति बहुत पतली होती है और उनमें रुधिर वाहिकाओं का विस्तृत जाल होता है, इसलिए गैसों का विनिमय तेज़ी से होता है।", "વાયુકોષ્ઠોની દીવાલ ખૂબ પાતળી હોય છે અને તેમાં રુધિરવાહિનીઓનું વિસ્તૃત જાળું હોય છે, તેથી વાયુઓની આપ-લે ઝડપથી થાય છે.")})
add("it4.q1", ("मानव में वहन तंत्र के घटक कौन-से हैं? इन घटकों के क्या कार्य हैं?", "મનુષ્યમાં વહનતંત્રના ઘટકો કયા છે? આ ઘટકોનાં કાર્યો શાં છે?"),
    {0: ("हृदय: पूरे शरीर में रुधिर पंप करता है।", "હૃદય: આખા શરીરમાં રુધિર પંપ કરે છે."), 1: ("रुधिर वाहिकाएँ: धमनियाँ रुधिर को हृदय से दूर ले जाती हैं, शिराएँ उसे वापस लाती हैं, और केशिकाएँ कोशिकाओं से पदार्थों का विनिमय करती हैं।", "રુધિરવાહિનીઓ: ધમનીઓ રુધિરને હૃદયથી દૂર લઈ જાય છે, શિરાઓ તેને પાછું લાવે છે, અને કેશિકાઓ કોષો સાથે પદાર્થોની આપ-લે કરે છે."),
     2: ("रुधिर: प्लैज्मा भोजन, कार्बन डाइऑक्साइड और अपशिष्ट ले जाता है; लाल रुधिर कणिकाएँ ऑक्सीजन ले जाती हैं; प्लेटलेट्स थक्का बनाने में सहायता करती हैं। लसीका ऊतक तरल लौटाती है और अवशोषित वसा ले जाती है।",
         "રુધિર: રુધિરરસ ખોરાક, કાર્બન ડાયૉક્સાઇડ અને કચરો લઈ જાય છે; રક્તકણો ઑક્સિજન લઈ જાય છે; ત્રાકકણો રુધિર જામવામાં મદદ કરે છે. લસિકા પેશીય પ્રવાહી પાછું લાવે છે અને શોષાયેલી ચરબી લઈ જાય છે.")})
add("it4.q2", ("स्तनधारी तथा पक्षियों में ऑक्सीजनित तथा विऑक्सीजनित रुधिर को अलग करना क्यों आवश्यक है?", "સસ્તનો અને પક્ષીઓમાં ઑક્સિજનયુક્ત અને ઑક્સિજનરહિત રુધિરને અલગ રાખવું કેમ જરૂરી છે?"),
    {0: ("अलग रखने से शरीर को ऑक्सीजन की अत्यंत दक्ष आपूर्ति होती है।", "અલગ રાખવાથી શરીરને ઑક્સિજનનો અત્યંત કાર્યક્ષમ પુરવઠો મળે છે."),
     1: ("पक्षियों और स्तनधारियों को शरीर का ताप स्थिर रखने के लिए बहुत ऊर्जा चाहिए, इसलिए उन्हें यह दक्ष आपूर्ति चाहिए।", "પક્ષીઓ અને સસ્તનોને શરીરનું તાપમાન અચળ રાખવા ઘણી ઊર્જા જોઈએ, તેથી તેમને આ કાર્યક્ષમ પુરવઠો જોઈએ.")})
add("it4.q3", ("उच्च संगठित पादप में वहन तंत्र के घटक क्या हैं?", "ઉચ્ચ કક્ષાની વનસ્પતિમાં વહનતંત્રના ઘટકો કયા છે?"),
    {0: ("जाइलम: जल और खनिजों को जड़ों से पौधे के अन्य भागों तक ले जाता है।", "જલવાહક: પાણી અને ખનિજોને મૂળમાંથી વનસ્પતિના બીજા ભાગો સુધી લઈ જાય છે."), 1: ("फ्लोएम: पत्तियों में बने भोजन को पौधे के अन्य भागों तक ले जाता है।", "અન્નવાહક: પર્ણોમાં બનેલા ખોરાકને વનસ્પતિના બીજા ભાગો સુધી લઈ જાય છે.")})
add("it4.q4", ("पादप में जल और खनिज लवण का वहन कैसे होता है?", "વનસ્પતિમાં પાણી અને ખનિજ ક્ષારોનું વહન કેવી રીતે થાય છે?"),
    {0: ("जड़, तने और पत्तियों की जाइलम वाहिकाएँ और वाहिनिकाएँ जल-संवहन की एक सतत प्रणाली बनाती हैं।", "મૂળ, પ્રકાંડ અને પર્ણોની જલવાહિનીઓ અને જલવાહિનિકીઓ પાણીના વહનની એક સળંગ પ્રણાલી બનાવે છે."),
     1: ("जड़ की कोशिकाएँ आयनों को सक्रिय रूप से लेती हैं, जिससे मिट्टी से जल जड़ में आता है और ऊपर धकेला जाता है (मूल दाब, रात में मुख्य बल)।", "મૂળના કોષો આયનોને સક્રિય રીતે લે છે, જેથી જમીનમાંથી પાણી મૂળમાં આવે છે અને ઉપર ધકેલાય છે (મૂળદાબ, રાત્રે મુખ્ય બળ)."),
     2: ("पत्तियों से रंध्रों द्वारा जल का वाष्पन (वाष्पोत्सर्जन) होता है; इससे एक चूषण, वाष्पोत्सर्जन खिंचाव, बनता है जो दिन में जल को जाइलम में ऊपर खींचता है।", "પર્ણોમાંથી વાયુરંધ્રો દ્વારા પાણીનું બાષ્પીભવન (બાષ્પોત્સર્જન) થાય છે; તેનાથી એક ખેંચાણ, બાષ્પોત્સર્જનનું ખેંચાણ, સર્જાય છે જે દિવસે પાણીને જલવાહકમાં ઉપર ખેંચે છે.")})
add("it4.q5", ("पादप में भोजन का स्थानांतरण कैसे होता है?", "વનસ્પતિમાં ખોરાકનું સ્થાનાંતરણ કેવી રીતે થાય છે?"),
    {0: ("भोजन (सुक्रोज़ और अन्य पदार्थ) फ्लोएम द्वारा ऊपर और नीचे दोनों ओर ले जाया जाता है; यह स्थानांतरण है।", "ખોરાક (સુક્રોઝ અને બીજા પદાર્થો) અન્નવાહક દ્વારા ઉપર અને નીચે બંને દિશામાં લઈ જવાય છે; આ સ્થાનાંતરણ છે."),
     1: ("ATP की ऊर्जा से सुक्रोज़ फ्लोएम में भेजा जाता है; परासरण से जल अंदर आता है, और दाब भोजन को आवश्यकता वाले स्थान तक पहुँचाता है।", "ATP ની ઊર્જાથી સુક્રોઝ અન્નવાહકમાં મોકલાય છે; આસૃતિથી પાણી અંદર આવે છે, અને દબાણ ખોરાકને જરૂરિયાતના સ્થાને પહોંચાડે છે.")})
add("it5.q1", ("वृक्काणु (नेफ्रॉन) की रचना तथा क्रियाविधि का वर्णन कीजिए।", "ઉત્સર્ગ એકમ (નેફ્રૉન) ની રચના અને કાર્યપદ્ધતિનું વર્ણન કરો."),
    {0: ("रचना: कप के आकार का बोमन संपुट, जिसमें केशिकाओं का गुच्छ (केशिका गुच्छ) होता है, उसके बाद एक लंबी नलिका जो संग्राहक वाहिनी से जुड़ती है।", "રચના: પ્યાલા આકારની બાઉમેનની કોથળી, જેમાં કેશિકાઓનો ગુચ્છ (રુધિરકેશિકાગુચ્છ) હોય છે, પછી એક લાંબી નલિકા જે સંગ્રાહક નલિકા સાથે જોડાય છે."),
     1: ("निस्यंदन: केशिका गुच्छ में रुधिर का निस्यंदन होता है, और निस्यंद बोमन संपुट में जाता है।", "ગાળણ: રુધિરકેશિકાગુચ્છમાં રુધિરનું ગાળણ થાય છે, અને ગાળણ બાઉમેનની કોથળીમાં જાય છે."),
     2: ("पुनरवशोषण: नलिका में ग्लूकोज़, अमीनो अम्ल, लवण और जल की प्रमुख मात्रा पुनः अवशोषित होती है; शेष मूत्र है।", "પુનઃશોષણ: નલિકામાં ગ્લુકોઝ, એમિનો ઍસિડ, ક્ષાર અને પાણીના મોટા ભાગનું પુનઃશોષણ થાય છે; બાકીનું મૂત્ર છે.")})
add("it5.q2", ("उत्सर्जी उत्पाद से छुटकारा पाने के लिए पादप किन विधियों का उपयोग करते हैं?", "ઉત્સર્ગ પદાર્થોનો નિકાલ કરવા વનસ્પતિ કઈ પદ્ધતિઓ વાપરે છે?"),
    {0: ("ऑक्सीजन और अतिरिक्त जल रंध्रों से निकाले जाते हैं।", "ઑક્સિજન અને વધારાનું પાણી વાયુરંધ્રો દ્વારા દૂર કરાય છે."),
     1: ("अन्य अपशिष्ट रिक्तिकाओं या पुराने जाइलम में संचित होते हैं, गिरती पत्तियों के साथ हटते हैं, गोंद और रेज़िन के रूप में संचित होते हैं, या मिट्टी में उत्सर्जित होते हैं।", "બીજો કચરો રસધાનીઓ કે જૂના જલવાહકમાં સંગ્રહાય છે, ખરતાં પર્ણો સાથે દૂર થાય છે, ગુંદર અને રાળ સ્વરૂપે સંગ્રહાય છે, કે જમીનમાં ઉત્સર્જિત થાય છે.")})
add("it5.q3", ("मूत्र बनने की मात्रा का नियमन किस प्रकार होता है?", "મૂત્ર બનવાના પ્રમાણનું નિયમન કેવી રીતે થાય છે?"),
    {0: ("यह शरीर में अतिरिक्त जल और घुले अपशिष्ट की मात्रा पर निर्भर है।", "તે શરીરમાં વધારાના પાણી અને ઓગળેલા કચરાના પ્રમાણ પર આધાર રાખે છે."),
     1: ("शरीर में जल कम होने पर नलिकाओं में अधिक जल पुनः अवशोषित होता है और कम मूत्र बनता है; अतिरिक्त जल होने पर अधिक मूत्र बनता है।", "શરીરમાં પાણી ઓછું હોય ત્યારે નલિકાઓમાં વધુ પાણીનું પુનઃશોષણ થાય છે અને ઓછું મૂત્ર બને છે; વધારાનું પાણી હોય ત્યારે વધુ મૂત્ર બને છે.")})

# Exercises
mc("ex.q1", ("मनुष्य में वृक्क एक तंत्र का भाग है, जो संबंधित है", "મનુષ્યમાં મૂત્રપિંડ જે તંત્રનો ભાગ છે તે સંકળાયેલું છે"), ("वृक्क रुधिर से अपशिष्ट छानकर मूत्र बनाते हैं।", "મૂત્રપિંડ રુધિરમાંથી કચરો ગાળીને મૂત્ર બનાવે છે."),
   {"nutrition.": (("पोषण से।", "પોષણ સાથે."), ("पोषण भोजन लेने से संबंधित है।", "પોષણ ખોરાક લેવા સાથે સંકળાયેલું છે.")), "respiration.": (("श्वसन से।", "શ્વસન સાથે."), ("फुफ्फुस श्वसन के लिए हैं।", "ફેફસાં શ્વસન માટે છે.")),
    "excretion.": (("उत्सर्जन से।", "ઉત્સર્જન સાથે."), OK), "transportation.": (("परिवहन से।", "વહન સાથે."), ("हृदय और रुधिर वाहिकाएँ पदार्थों का वहन करती हैं।", "હૃદય અને રુધિરવાહિનીઓ પદાર્થોનું વહન કરે છે."))})
mc("ex.q2", ("पादप में जाइलम उत्तरदायी है", "વનસ્પતિમાં જલવાહક જવાબદાર છે"), ("जाइलम जल और खनिज ले जाता है; फ्लोएम भोजन ले जाता है।", "જલવાહક પાણી અને ખનિજો લઈ જાય છે; અન્નવાહક ખોરાક લઈ જાય છે."),
   {"transport of water.": (("जल के वहन के लिए।", "પાણીના વહન માટે."), OK), "transport of food.": (("भोजन के वहन के लिए।", "ખોરાકના વહન માટે."), ("फ्लोएम भोजन ले जाता है।", "અન્નવાહક ખોરાક લઈ જાય છે.")),
    "transport of amino acids.": (("अमीनो अम्ल के वहन के लिए।", "એમિનો ઍસિડના વહન માટે."), ("अमीनो अम्ल फ्लोएम में चलते हैं।", "એમિનો ઍસિડ અન્નવાહકમાં વહે છે.")),
    "transport of oxygen.": (("ऑक्सीजन के वहन के लिए।", "ઑક્સિજનના વહન માટે."), ("ऑक्सीजन रंध्रों से अंदर आकर विसरित होती है।", "ઑક્સિજન વાયુરંધ્રો દ્વારા અંદર આવીને પ્રસરે છે."))})
mc("ex.q3", ("स्वपोषी पोषण के लिए आवश्यक है", "સ્વાવલંબી પોષણ માટે જરૂરી છે"), ("प्रकाशसंश्लेषण के लिए कार्बन डाइऑक्साइड, जल, क्लोरोफ़िल और सूर्य का प्रकाश चाहिए।", "પ્રકાશસંશ્લેષણ માટે કાર્બન ડાયૉક્સાઇડ, પાણી, હરિતદ્રવ્ય અને સૂર્યપ્રકાશ જોઈએ."),
   {"carbon dioxide and water.": (("कार्बन डाइऑक्साइड तथा जल।", "કાર્બન ડાયૉક્સાઇડ અને પાણી."), ("ये आवश्यक हैं, पर क्लोरोफ़िल और सूर्य का प्रकाश भी।", "આ જરૂરી છે, પણ હરિતદ્રવ્ય અને સૂર્યપ્રકાશ પણ.")),
    "chlorophyll.": (("क्लोरोफ़िल।", "હરિતદ્રવ્ય."), ("क्लोरोफ़िल आवश्यक है, पर बाकी भी।", "હરિતદ્રવ્ય જરૂરી છે, પણ બાકીનાં પણ.")), "sunlight.": (("सूर्य का प्रकाश।", "સૂર્યપ્રકાશ."), ("सूर्य का प्रकाश आवश्यक है, पर बाकी भी।", "સૂર્યપ્રકાશ જરૂરી છે, પણ બાકીનાં પણ.")),
    "all of the above.": (("उपरोक्त सभी।", "ઉપરનાં બધાં."), OK)})
mc("ex.q4", ("पाइरुवेट के विखंडन से यह कार्बन डाइऑक्साइड, जल तथा ऊर्जा देता है और यह क्रिया होती है", "પાયરુવેટના વિઘટનથી કાર્બન ડાયૉક્સાઇડ, પાણી અને ઊર્જા મળે છે અને આ ક્રિયા થાય છે"), ("पाइरुवेट का वायवीय विखंडन माइटोकॉन्ड्रिया में होता है।", "પાયરુવેટનું જારક વિઘટન કણાભસૂત્રમાં થાય છે."),
   {"cytoplasm.": (("कोशिकाद्रव्य में।", "કોષરસમાં."), ("यहाँ केवल पहला चरण, ग्लूकोज़ से पाइरुवेट, होता है।", "અહીં ફક્ત પહેલું પગલું, ગ્લુકોઝથી પાયરુવેટ, થાય છે.")), "mitochondria.": (("माइटोकॉन्ड्रिया में।", "કણાભસૂત્રમાં."), OK),
    "chloroplast.": (("हरित लवक में।", "હરિતકણમાં."), ("हरित लवक प्रकाशसंश्लेषण करते हैं।", "હરિતકણ પ્રકાશસંશ્લેષણ કરે છે.")), "nucleus.": (("केंद्रक में।", "કોષકેન્દ્રમાં."), ("केंद्रक भोजन नहीं तोड़ता।", "કોષકેન્દ્ર ખોરાક તોડતું નથી."))})
add("ex.q5", ("हमारे शरीर में वसा का पाचन कैसे होता है? यह प्रक्रम कहाँ होता है?", "આપણા શરીરમાં ચરબીનું પાચન કેવી રીતે થાય છે? આ ક્રિયા ક્યાં થાય છે?"),
    {0: ("वसा का पाचन क्षुद्रांत्र में होता है।", "ચરબીનું પાચન નાના આંતરડામાં થાય છે."), 1: ("यकृत से आया पित्त रस वसा की बड़ी गोलिकाओं को छोटी गोलिकाओं में तोड़ता है (इमल्सीकरण) और माध्यम को क्षारीय बनाता है।", "યકૃતમાંથી આવેલો પિત્તરસ ચરબીની મોટી ગોલિકાઓને નાની ગોલિકાઓમાં તોડે છે (તૈલોદીકરણ) અને માધ્યમને આલ્કલાઇન બનાવે છે."),
     2: ("अग्न्याशय का लाइपेज इमल्सीकृत वसा को पचाता है, और आंत्र रस अंत में उन्हें वसा-अम्ल और ग्लिसरॉल में बदल देता है।", "સ્વાદુપિંડનો લાયપેઝ તૈલોદીકૃત ચરબીને પચાવે છે, અને આંત્રરસ છેવટે તેને ફેટી ઍસિડ અને ગ્લિસરોલમાં ફેરવે છે.")})
add("ex.q6", ("भोजन के पाचन में लार की क्या भूमिका है?", "ખોરાકના પાચનમાં લાળની ભૂમિકા શી છે?"),
    {0: ("लार भोजन को गीला करती है, जिससे उसे चबाना और निगलना आसान होता है।", "લાળ ખોરાકને ભીનો કરે છે, જેથી તેને ચાવવો અને ગળવો સહેલો બને છે."), 1: ("इसमें लार एमिलेस एंज़ाइम होता है, जो मंड को शर्करा में तोड़ता है।", "તેમાં લાળરસીય એમાયલેઝ ઉત્સેચક હોય છે, જે સ્ટાર્ચને શર્કરામાં તોડે છે.")})
add("ex.q7", ("स्वपोषी पोषण के लिए आवश्यक परिस्थितियाँ कौन-सी हैं और उसके उपोत्पाद क्या हैं?", "સ્વાવલંબી પોષણ માટે જરૂરી પરિસ્થિતિઓ કઈ છે અને તેની આડપેદાશો શી છે?"),
    {0: ("परिस्थितियाँ: सूर्य का प्रकाश, क्लोरोफ़िल, कार्बन डाइऑक्साइड और जल।", "પરિસ્થિતિઓ: સૂર્યપ્રકાશ, હરિતદ્રવ્ય, કાર્બન ડાયૉક્સાઇડ અને પાણી."), 1: ("उत्पाद: कार्बोहाइड्रेट (ग्लूकोज़, मंड के रूप में संचित), और उपोत्पाद के रूप में ऑक्सीजन निकलती है।", "નીપજ: કાર્બોદિત (ગ્લુકોઝ, સ્ટાર્ચ સ્વરૂપે સંગ્રહાય છે), અને આડપેદાશ તરીકે ઑક્સિજન મુક્ત થાય છે."),
     2: ("सूर्य के प्रकाश और क्लोरोफ़िल की उपस्थिति में: {0}", "સૂર્યપ્રકાશ અને હરિતદ્રવ્યની હાજરીમાં: {0}")})
add("ex.q8", ("वायवीय तथा अवायवीय श्वसन में क्या अंतर हैं? कुछ जीवों के नाम लिखिए जिनमें अवायवीय श्वसन होता है।", "જારક અને અજારક શ્વસન વચ્ચે શા તફાવત છે? જેમાં અજારક શ્વસન થાય છે તેવા કેટલાક સજીવોનાં નામ આપો."),
    {0: ("वायवीय श्वसन में ऑक्सीजन लगती है और यह माइटोकॉन्ड्रिया में होता है; अवायवीय श्वसन ऑक्सीजन के बिना, कोशिकाद्रव्य में होता है।", "જારક શ્વસનમાં ઑક્સિજન વપરાય છે અને તે કણાભસૂત્રમાં થાય છે; અજારક શ્વસન ઑક્સિજન વિના, કોષરસમાં થાય છે."),
     1: ("वायवीय श्वसन से कार्बन डाइऑक्साइड, जल और कहीं अधिक ऊर्जा मिलती है; अवायवीय श्वसन से एथेनॉल और कार्बन डाइऑक्साइड (या लैक्टिक अम्ल) और कम ऊर्जा मिलती है।", "જારક શ્વસનથી કાર્બન ડાયૉક્સાઇડ, પાણી અને ઘણી વધુ ઊર્જા મળે છે; અજારક શ્વસનથી ઇથેનૉલ અને કાર્બન ડાયૉક્સાઇડ (કે લેક્ટિક ઍસિડ) અને ઓછી ઊર્જા મળે છે."),
     2: ("जीव: यीस्ट, कुछ जीवाणु और फ़ीताकृमि (हमारी पेशी कोशिकाएँ भी थोड़े समय के लिए अवायवीय श्वसन करती हैं)।", "સજીવો: યીસ્ટ, કેટલાક બૅક્ટેરિયા અને પટ્ટીકૃમિ (આપણા સ્નાયુકોષો પણ થોડા સમય માટે અજારક શ્વસન કરે છે).")})
add("ex.q9", ("गैसों के अधिकतम विनिमय के लिए कूपिकाएँ किस प्रकार अभिकल्पित हैं?", "વાયુઓની મહત્તમ આપ-લે માટે વાયુકોષ્ઠો કેવી રીતે રચાયેલા છે?"),
    {0: ("लाखों कूपिकाएँ होती हैं, जो विनिमय के लिए बहुत बड़ी सतह (लगभग 80 m²) देती हैं।", "લાખો વાયુકોષ્ઠો હોય છે, જે આપ-લે માટે ખૂબ મોટી સપાટી (આશરે 80 m²) આપે છે."),
     1: ("इनकी भित्ति बहुत पतली होती है और इनमें केशिकाओं का विस्तृत जाल होता है, इसलिए गैसें वायु और रुधिर के बीच तेज़ी से विसरित होती हैं।", "તેમની દીવાલ ખૂબ પાતળી હોય છે અને તેમાં કેશિકાઓનું વિસ્તૃત જાળું હોય છે, તેથી વાયુઓ હવા અને રુધિર વચ્ચે ઝડપથી પ્રસરે છે.")})
add("ex.q10", ("हमारे शरीर में हीमोग्लोबिन की कमी के क्या परिणाम हो सकते हैं?", "આપણા શરીરમાં હિમોગ્લોબિનની ઊણપનાં શાં પરિણામો આવી શકે?"),
    {0: ("हीमोग्लोबिन ऑक्सीजन ले जाता है, इसलिए कोशिकाओं तक कम ऑक्सीजन पहुँचती है और कम ऊर्जा मुक्त होती है।", "હિમોગ્લોબિન ઑક્સિજનનું વહન કરે છે, તેથી કોષો સુધી ઓછો ઑક્સિજન પહોંચે છે અને ઓછી ઊર્જા મુક્ત થાય છે."),
     1: ("व्यक्ति थका और कमज़ोर अनुभव करता है, पीला दिखता है और जल्दी हाँफने लगता है: इस अवस्था को रक्ताल्पता (एनीमिया) कहते हैं।", "વ્યક્તિ થાકેલી અને નબળી લાગે છે, ફિક્કી દેખાય છે અને જલદી હાંફી જાય છે: આ સ્થિતિને પાંડુરોગ (એનીમિયા) કહે છે.")})
add("ex.q11", ("मनुष्य में दोहरा परिसंचरण की व्याख्या कीजिए। यह क्यों आवश्यक है?", "મનુષ્યમાં બેવડું પરિવહન સમજાવો. તે કેમ જરૂરી છે?"),
    {0: ("शरीर से आया विऑक्सीजनित रुधिर दाएँ अलिंद में आता है, दाएँ निलय में जाता है और फुफ्फुसों में पंप किया जाता है।", "શરીરમાંથી આવેલું ઑક્સિજનરહિત રુધિર જમણા કર્ણકમાં આવે છે, જમણા ક્ષેપકમાં જાય છે અને ફેફસાંમાં પંપ થાય છે."),
     1: ("फुफ्फुसों में यह ऑक्सीजन लेता है और कार्बन डाइऑक्साइड छोड़ता है; ऑक्सीजनित रुधिर बाएँ अलिंद में लौटता है।", "ફેફસાંમાં તે ઑક્સિજન લે છે અને કાર્બન ડાયૉક્સાઇડ છોડે છે; ઑક્સિજનયુક્ત રુધિર ડાબા કર્ણકમાં પાછું આવે છે."),
     2: ("बाएँ अलिंद से यह बाएँ निलय में जाता है और शेष शरीर में पंप किया जाता है।", "ડાબા કર્ણકમાંથી તે ડાબા ક્ષેપકમાં જાય છે અને બાકીના શરીરમાં પંપ થાય છે."),
     3: ("इस प्रकार शरीर के एक चक्र में रुधिर हृदय से दो बार गुज़रता है: यही दोहरा परिसंचरण है। वाल्व रुधिर को उलटा बहने से रोकते हैं।", "આમ શરીરના એક ચક્રમાં રુધિર હૃદયમાંથી બે વાર પસાર થાય છે: આ જ બેવડું પરિવહન છે. વાલ્વ રુધિરને ઊલટું વહેતું અટકાવે છે."),
     4: ("यह ऑक्सीजनित और विऑक्सीजनित रुधिर को अलग रखता है, जिससे ऑक्सीजन की दक्ष आपूर्ति होती है, जो मनुष्य को अधिक ऊर्जा उपयोग और स्थिर शरीर ताप के लिए चाहिए।", "તે ઑક્સિજનયુક્ત અને ઑક્સિજનરહિત રુધિરને અલગ રાખે છે, જેથી ઑક્સિજનનો કાર્યક્ષમ પુરવઠો મળે છે, જે મનુષ્યને વધુ ઊર્જા-વપરાશ અને અચળ શરીર-તાપમાન માટે જોઈએ.")})
add("ex.q12", ("जाइलम तथा फ्लोएम में पदार्थों के वहन में क्या अंतर है?", "જલવાહક અને અન્નવાહકમાં પદાર્થોના વહનમાં શો તફાવત છે?"),
    {0: ("जाइलम जल और खनिज ले जाता है; फ्लोएम भोजन (सुक्रोज़, अमीनो अम्ल) ले जाता है।", "જલવાહક પાણી અને ખનિજો લઈ જાય છે; અન્નવાહક ખોરાક (સુક્રોઝ, એમિનો ઍસિડ) લઈ જાય છે."),
     1: ("जाइलम में वहन केवल ऊपर की ओर, जड़ों से पत्तियों तक, होता है; फ्लोएम में ऊपर और नीचे दोनों ओर।", "જલવાહકમાં વહન ફક્ત ઉપર તરફ, મૂળથી પર્ણો સુધી, થાય છે; અન્નવાહકમાં ઉપર અને નીચે બંને તરફ."),
     2: ("जाइलम के वहन में कोशिकाओं की ऊर्जा नहीं लगती (वाष्पोत्सर्जन खिंचाव, मूल दाब); फ्लोएम के वहन में ATP की ऊर्जा लगती है।", "જલવાહકના વહનમાં કોષોની ઊર્જા વપરાતી નથી (બાષ્પોત્સર્જનનું ખેંચાણ, મૂળદાબ); અન્નવાહકના વહનમાં ATP ની ઊર્જા વપરાય છે.")})
add("ex.q13", ("फुफ्फुस में कूपिकाओं की तथा वृक्क में वृक्काणु (नेफ्रॉन) की रचना तथा क्रियाविधि की तुलना कीजिए।", "ફેફસાંમાં વાયુકોષ્ઠોની અને મૂત્રપિંડમાં ઉત્સર્ગ એકમ (નેફ્રૉન) ની રચના અને કાર્યપદ્ધતિની સરખામણી કરો."),
    {0: ("रचना, कूपिकाएँ: श्वसनिकाओं के सिरों पर सूक्ष्म गुब्बारे जैसी थैलियाँ, बहुत पतली भित्ति और केशिकाओं के जाल के साथ।", "રચના, વાયુકોષ્ઠો: શ્વસનિકાઓના છેડે સૂક્ષ્મ ફુગ્ગા જેવી કોથળીઓ, ખૂબ પાતળી દીવાલ અને કેશિકાઓના જાળા સાથે."),
     1: ("रचना, वृक्काणु: केशिका गुच्छ वाला बोमन संपुट और एक लंबी नलिका, जो भी केशिकाओं से घिरी होती है।", "રચના, ઉત્સર્ગ એકમ: રુધિરકેશિકાગુચ્છવાળી બાઉમેનની કોથળી અને એક લાંબી નલિકા, જે પણ કેશિકાઓથી ઘેરાયેલી હોય છે."),
     2: ("कार्य, कूपिकाएँ: गैसों का विनिमय; ऑक्सीजन रुधिर में और कार्बन डाइऑक्साइड बाहर विसरित होती है।", "કાર્ય, વાયુકોષ્ઠો: વાયુઓની આપ-લે; ઑક્સિજન રુધિરમાં અને કાર્બન ડાયૉક્સાઇડ બહાર પ્રસરે છે."),
     3: ("कार्य, वृक्काणु: रुधिर का निस्यंदन, उपयोगी पदार्थों का पुनरवशोषण और मूत्र का निर्माण।", "કાર્ય, ઉત્સર્ગ એકમ: રુધિરનું ગાળણ, ઉપયોગી પદાર્થોનું પુનઃશોષણ અને મૂત્રનું નિર્માણ."),
     4: ("दोनों की सतह बहुत बड़ी और भित्ति पतली होती है, जो रुधिर केशिकाओं के निकट संपर्क में रहती है।", "બંનેની સપાટી ખૂબ મોટી અને દીવાલ પાતળી હોય છે, જે રુધિરકેશિકાઓના નજીકના સંપર્કમાં રહે છે.")})

# Sample paper
mc("sqp1", ("वह समूह चुनिए जिसमें सभी जीवों का पोषण का प्रकार समान है।", "એવું જૂથ પસંદ કરો જેમાં બધા સજીવોની પોષણ-પદ્ધતિ સમાન છે."), ("अमरबेल, किलनी, जूँ, जोंक और फ़ीताकृमि सभी परजीवी हैं।", "અમરવેલ, બગાઈ, જૂ, જળો અને પટ્ટીકૃમિ બધાં પરોપજીવી છે."),
   {"Cuscuta, yeast, legumes, leeches and tapeworm": (("अमरबेल, यीस्ट, फलीदार पौधे, जोंक और फ़ीताकृमि", "અમરવેલ, યીસ્ટ, શિંગવાળી વનસ્પતિ, જળો અને પટ્ટીકૃમિ"), ("यीस्ट मृतजीवी है और फलीदार पौधे अपना भोजन स्वयं बनाते हैं।", "યીસ્ટ મૃતોપજીવી છે અને શિંગવાળી વનસ્પતિ પોતાનો ખોરાક જાતે બનાવે છે.")),
    "Cactus, ticks, lice, leeches and cow": (("नागफनी, किलनी, जूँ, जोंक और गाय", "થોર, બગાઈ, જૂ, જળો અને ગાય"), ("नागफनी स्वपोषी है और गाय परजीवी नहीं है।", "થોર સ્વાવલંબી છે અને ગાય પરોપજીવી નથી.")),
    "Cuscuta, ticks, lice, leeches and tapeworm": (("अमरबेल, किलनी, जूँ, जोंक और फ़ीताकृमि", "અમરવેલ, બગાઈ, જૂ, જળો અને પટ્ટીકૃમિ"), OK),
    "Cactus, grass, lice, lion and tapeworm": (("नागफनी, घास, जूँ, शेर और फ़ीताकृमि", "થોર, ઘાસ, જૂ, સિંહ અને પટ્ટીકૃમિ"), ("नागफनी और घास स्वपोषी हैं; शेर शिकारी है।", "થોર અને ઘાસ સ્વાવલંબી છે; સિંહ શિકારી છે."))})
mc("sqp2", ("कौन-सा विकल्प ऑक्सीजन की कमी होने पर हमारी पेशी कोशिकाओं में ग्लूकोज़ के विखंडन से बने उत्पाद दर्शाता है?", "કયો વિકલ્પ ઑક્સિજનની ઊણપ હોય ત્યારે આપણા સ્નાયુકોષોમાં ગ્લુકોઝના વિઘટનથી બનતી નીપજો દર્શાવે છે?"),
   ("ऑक्सीजन की कमी में हमारी पेशी कोशिकाएँ पाइरुवेट को लैक्टिक अम्ल में बदलती हैं, जिससे थोड़ी ऊर्जा मुक्त होती है।", "ઑક્સિજનની ઊણપમાં આપણા સ્નાયુકોષો પાયરુવેટને લેક્ટિક ઍસિડમાં ફેરવે છે, જેથી થોડી ઊર્જા મુક્ત થાય છે."),
   {"Ethanol + carbon dioxide + Energy": (("एथेनॉल + कार्बन डाइऑक्साइड + ऊर्जा", "ઇથેનૉલ + કાર્બન ડાયૉક્સાઇડ + ઊર્જા"), ("यह यीस्ट में होता है।", "આ યીસ્ટમાં થાય છે.")), "Lactic acid + Energy": (("लैक्टिक अम्ल + ऊर्जा", "લેક્ટિક ઍસિડ + ઊર્જા"), OK),
    "Lactic acid + carbon monoxide + Energy": (("लैक्टिक अम्ल + कार्बन मोनोऑक्साइड + ऊर्जा", "લેક્ટિક ઍસિડ + કાર્બન મોનૉક્સાઇડ + ઊર્જા"), ("कार्बन मोनोऑक्साइड नहीं बनती।", "કાર્બન મોનૉક્સાઇડ બનતો નથી.")),
    "Carbon dioxide + Water + Energy": (("कार्बन डाइऑक्साइड + जल + ऊर्जा", "કાર્બન ડાયૉક્સાઇડ + પાણી + ઊર્જા"), ("इसके लिए पर्याप्त ऑक्सीजन चाहिए।", "તેના માટે પૂરતો ઑક્સિજન જોઈએ."))})
add("sqp10", ("जंतुओं के विपरीत, पौधों के कोई उत्सर्जी उत्पाद नहीं होते क्योंकि वे भोजन नहीं खाते। औचित्य सहित इस कथन पर टिप्पणी कीजिए।", "પ્રાણીઓથી વિપરીત, વનસ્પતિને કોઈ ઉત્સર્ગ પદાર્થો હોતા નથી કારણ કે તે ખોરાક ખાતી નથી. કારણ સાથે આ વિધાન પર ટિપ્પણી કરો."),
    {0: ("कथन गलत है: पौधे भी उत्सर्जी उत्पाद बनाते हैं, पर उनसे जंतुओं से भिन्न तरीकों से छुटकारा पाते हैं।", "વિધાન ખોટું છે: વનસ્પતિ પણ ઉત્સર્ગ પદાર્થો બનાવે છે, પણ પ્રાણીઓથી જુદી રીતે તેમનો નિકાલ કરે છે."),
     1: ("ऑक्सीजन और अतिरिक्त जल रंध्रों से निकलते हैं; अन्य अपशिष्ट रिक्तिकाओं, मृत कोशिकाओं, गोंद और रेज़िन में संचित होते हैं, या गिरती पत्तियों के साथ हटते हैं।", "ઑક્સિજન અને વધારાનું પાણી વાયુરંધ્રો દ્વારા નીકળે છે; બીજો કચરો રસધાનીઓ, મૃત કોષો, ગુંદર અને રાળમાં સંગ્રહાય છે, કે ખરતાં પર્ણો સાથે દૂર થાય છે.")})
add("sqp11a", ("निम्नलिखित जीवों के हृदय में कितने कोष्ठ होते हैं? इनके शरीर में ऑक्सीजनित और विऑक्सीजनित रुधिर का मिश्रण कैसे रोका जाता है?\n\n(i) मछलियाँ\n\n(ii) मनुष्य", "નીચેના સજીવોના હૃદયમાં કેટલા ખંડો હોય છે? તેમના શરીરમાં ઑક્સિજનયુક્ત અને ઑક્સિજનરહિત રુધિરનું મિશ્રણ કેવી રીતે અટકાવાય છે?\n\n(i) માછલીઓ\n\n(ii) મનુષ્ય"),
    {0: ("(i) मछलियाँ: दो कोष्ठ। रुधिर क्लोमों में पंप होता है, वहाँ ऑक्सीजनित होकर सीधे शेष शरीर में जाता है, इसलिए यह एक चक्र में हृदय से केवल एक बार गुज़रता है।", "(i) માછલીઓ: બે ખંડો. રુધિર ઝાલરોમાં પંપ થાય છે, ત્યાં ઑક્સિજનયુક્ત થઈને સીધું બાકીના શરીરમાં જાય છે, તેથી તે એક ચક્રમાં હૃદયમાંથી ફક્ત એક વાર પસાર થાય છે."),
     1: ("(ii) मनुष्य: चार कोष्ठ। पट (सेप्टम) हृदय के दाएँ और बाएँ भागों को अलग करता है, जिससे मिश्रण रुकता है।", "(ii) મનુષ્ય: ચાર ખંડો. પડદો (સેપ્ટમ) હૃદયની જમણી અને ડાબી બાજુને અલગ કરે છે, જેથી મિશ્રણ અટકે છે.")})
add("sqp11b", ("पौधों में जल के वहन की क्रियाविधि समझाइए।", "વનસ્પતિમાં પાણીના વહનની કાર્યપદ્ધતિ સમજાવો."),
    {0: ("जड़ें आयनों को सक्रिय रूप से लेती हैं, जिससे सांद्रता में अंतर बनता है और जल मिट्टी से जड़ के जाइलम में आता है।", "મૂળ આયનોને સક્રિય રીતે લે છે, જેથી સાંદ્રતામાં તફાવત સર્જાય છે અને પાણી જમીનમાંથી મૂળના જલવાહકમાં આવે છે."),
     1: ("पत्तियों से वाष्पोत्सर्जन जाइलम की वाहिनिकाओं और वाहिकाओं में चूषण (वाष्पोत्सर्जन खिंचाव) बनाता है, जो जल को ऊपर खींचता है।", "પર્ણોમાંથી બાષ્પોત્સર્જન જલવાહકની જલવાહિનિકીઓ અને જલવાહિનીઓમાં ખેંચાણ (બાષ્પોત્સર્જનનું ખેંચાણ) સર્જે છે, જે પાણીને ઉપર ખેંચે છે.")})
add("sqp15", ("नेहा ने नाश्ते में उबले शकरकंद और उबले अंडे खाए। उसके द्वारा लिए गए भोजन के पाचन के कुछ चरणों को समझने में उसकी सहायता कीजिए।\n\n"
              "(i) इनमें से कौन-सा खाद्य पदार्थ प्रोटीन से भरपूर है? आहार नाल के किस भाग में इस घटक का पाचन शुरू होता है? यहाँ पाचन से जुड़े एंज़ाइम, आवश्यक परिस्थितियाँ और ग्रंथियों के नाम बताइए। "
              "अथवा इनमें से किस खाद्य पदार्थ में वसा है? इसका पाचन कैसे होता है? (2)\n\n(ii) इनमें से कौन-सा खाद्य पदार्थ मंड से भरपूर है? इसका पाचन कैसे शुरू होता है? (1)\n\n"
              "(iii) पाचन का प्रक्रम पूरा होते ही आहार नाल के किस भाग में पचा हुआ भोजन सबसे अधिक मात्रा में होगा? (1)",
              "નેહાએ નાસ્તામાં બાફેલાં શક્કરિયાં અને બાફેલાં ઈંડાં ખાધાં. તેણે લીધેલા ખોરાકના પાચનનાં કેટલાંક પગલાં સમજવામાં તેને મદદ કરો.\n\n"
              "(i) આમાંથી કયો ખોરાક પ્રોટીનથી ભરપૂર છે? અન્નમાર્ગના કયા ભાગમાં આ ઘટકનું પાચન શરૂ થાય છે? અહીં પાચન સાથે સંકળાયેલા ઉત્સેચકો, જરૂરી પરિસ્થિતિઓ અને ગ્રંથિઓનાં નામ આપો. "
              "અથવા આમાંથી કયા ખોરાકમાં ચરબી છે? તેનું પાચન કેવી રીતે થાય છે? (2)\n\n(ii) આમાંથી કયો ખોરાક સ્ટાર્ચથી ભરપૂર છે? તેનું પાચન કેવી રીતે શરૂ થાય છે? (1)\n\n"
              "(iii) પાચનની ક્રિયા પૂરી થતાં જ અન્નમાર્ગના કયા ભાગમાં પચેલો ખોરાક સૌથી વધુ પ્રમાણમાં હશે? (1)"),
    {0: ("(i) अंडे प्रोटीन से भरपूर हैं। इनका पाचन आमाशय में शुरू होता है: आमाशय की भित्ति की जठर ग्रंथियाँ हाइड्रोक्लोरिक अम्ल, पेप्सिन एंज़ाइम और श्लेष्मा छोड़ती हैं; अम्ल माध्यम को अम्लीय बनाता है ताकि पेप्सिन कार्य कर सके। "
         "अथवा अंडों में वसा है। यकृत का पित्त रस वसा की बड़ी गोलिकाओं को छोटी गोलिकाओं में तोड़ता है और माध्यम को क्षारीय बनाता है; अग्न्याशय का लाइपेज इमल्सीकृत वसा को पचाता है।",
         "(i) ઈંડાં પ્રોટીનથી ભરપૂર છે. તેનું પાચન જઠરમાં શરૂ થાય છે: જઠરની દીવાલની જઠરગ્રંથિઓ હાઇડ્રોક્લોરિક ઍસિડ, પેપ્સિન ઉત્સેચક અને શ્લેષ્મ સ્રવે છે; ઍસિડ માધ્યમને ઍસિડિક બનાવે છે જેથી પેપ્સિન કાર્ય કરી શકે. "
         "અથવા ઈંડાંમાં ચરબી છે. યકૃતનો પિત્તરસ ચરબીની મોટી ગોલિકાઓને નાની ગોલિકાઓમાં તોડે છે અને માધ્યમને આલ્કલાઇન બનાવે છે; સ્વાદુપિંડનો લાયપેઝ તૈલોદીકૃત ચરબીને પચાવે છે."),
     1: ("(ii) शकरकंद मंड से भरपूर हैं। मुँह की लार ग्रंथियों से आई लार का लार एमिलेस मंड को शर्करा में तोड़ना शुरू करता है।", "(ii) શક્કરિયાં સ્ટાર્ચથી ભરપૂર છે. મુખની લાળગ્રંથિઓમાંથી આવેલી લાળનો લાળરસીય એમાયલેઝ સ્ટાર્ચને શર્કરામાં તોડવાનું શરૂ કરે છે."),
     2: ("(iii) क्षुद्रांत्र, क्योंकि पाचन वहीं पूरा होता है।", "(iii) નાનું આંતરડું, કારણ કે પાચન ત્યાં જ પૂરું થાય છે.")})

