add("gseb2025_27", ("अमीबा में पोषण समझाइए।", "અમીબામાં પોષણ સમજાવો."),
    {0: ("अमीबा कोशिका की सतह के अस्थायी अँगुली जैसे प्रवर्धों (कूटपादों) से भोजन लेता है, जो खाद्य कण के ऊपर जुड़कर खाद्य रिक्तिका बनाते हैं।", "અમીબા કોષની સપાટીના કામચલાઉ આંગળી જેવા પ્રવર્ધો (ખોટા પગ) વડે ખોરાક લે છે, જે ખોરાકના કણ પર જોડાઈને ખોરાકધાની બનાવે છે."),
     1: ("खाद्य रिक्तिका के अंदर जटिल पदार्थ सरल पदार्थों में टूटकर कोशिकाद्रव्य में विसरित होते हैं; अपचित पदार्थ सतह पर लाकर बाहर निकाल दिया जाता है।", "ખોરાકધાનીની અંદર જટિલ પદાર્થો સાદા પદાર્થોમાં તૂટીને કોષરસમાં પ્રસરે છે; અપચિત પદાર્થ સપાટી પર લાવીને બહાર ફેંકાય છે.")})
add("gseb2025_36", ("मानव श्वसन तंत्र के अंग बताइए।", "માનવ શ્વસનતંત્રનાં અંગો જણાવો."),
    {0: ("नासाद्वार (नासा मार्ग), ग्रसनी, कंठ और श्वासनली।", "નાસિકાછિદ્રો (નાસામાર્ગ), કંઠનળી, સ્વરપેટી અને શ્વાસનળી."), 1: ("श्वसनी, श्वसनिकाएँ और कूपिकाओं सहित फुफ्फुस; डायाफ्राम और पसलियाँ श्वास में सहायता करते हैं।", "શ્વસનીઓ, શ્વસનિકાઓ અને વાયુકોષ્ઠો સહિત ફેફસાં; ઉરોદરપટલ અને પાંસળીઓ શ્વાસોચ્છ્વાસમાં મદદ કરે છે.")})
add("gseb2025_50", ("(a) लसीका पर संक्षिप्त टिप्पणी लिखिए।\n\n(b) उच्च संगठित पौधों में वहन तंत्र के घटक कौन-से हैं? उनके कार्य भी लिखिए।", "(a) લસિકા પર ટૂંકનોંધ લખો.\n\n(b) ઉચ્ચ કક્ષાની વનસ્પતિમાં વહનતંત્રના ઘટકો કયા છે? તેમનાં કાર્યો પણ લખો."),
    {0: ("(a) लसीका एक रंगहीन तरल है, जो केशिकाओं के छिद्रों से कोशिकाओं के बीच के स्थानों में निकले प्लैज्मा, प्रोटीन और रुधिर कोशिकाओं से बनता है; इसमें प्लैज्मा से कम प्रोटीन होता है।", "(a) લસિકા એક રંગવિહીન પ્રવાહી છે, જે કેશિકાઓનાં છિદ્રોમાંથી કોષો વચ્ચેની જગ્યામાં નીકળેલા રુધિરરસ, પ્રોટીન અને રુધિરકોષોમાંથી બને છે; તેમાં રુધિરરસ કરતાં ઓછું પ્રોટીન હોય છે."),
     1: ("यह आंत्र से पचे और अवशोषित वसा को ले जाता है और कोशिकाओं के बीच के स्थानों से अतिरिक्त तरल को वापस रुधिर में पहुँचाता है।", "તે આંતરડામાંથી પચેલી અને શોષાયેલી ચરબી લઈ જાય છે અને કોષો વચ્ચેની જગ્યામાંથી વધારાનું પ્રવાહી પાછું રુધિરમાં પહોંચાડે છે."),
     2: ("(b) जाइलम जल और खनिजों को जड़ों से दूसरे भागों तक ले जाता है; फ्लोएम भोजन को पत्तियों से दूसरे भागों तक ले जाता है।", "(b) જલવાહક પાણી અને ખનિજોને મૂળમાંથી બીજા ભાગો સુધી લઈ જાય છે; અન્નવાહક ખોરાકને પર્ણોમાંથી બીજા ભાગો સુધી લઈ જાય છે.")})
add("gseb2025_51", ("(a) स्वपोषी पोषण और विषमपोषी पोषण में क्या अंतर है?\n\n(b) वृक्काणु (नेफ्रॉन) की स्वच्छ और नामांकित संरचना बनाइए।", "(a) સ્વાવલંબી પોષણ અને પરાવલંબી પોષણ વચ્ચે શો તફાવત છે?\n\n(b) ઉત્સર્ગ એકમ (નેફ્રૉન) ની સ્વચ્છ અને નામનિર્દેશવાળી રચના દોરો."),
    {0: ("(a) स्वपोषी सूर्य के प्रकाश और क्लोरोफ़िल की सहायता से कार्बन डाइऑक्साइड और जल से अपना भोजन बनाते हैं (हरे पौधे); विषमपोषी दूसरों द्वारा बनाया भोजन लेते हैं (जंतु, कवक)।", "(a) સ્વાવલંબી સજીવો સૂર્યપ્રકાશ અને હરિતદ્રવ્યની મદદથી કાર્બન ડાયૉક્સાઇડ અને પાણીમાંથી પોતાનો ખોરાક બનાવે છે (લીલી વનસ્પતિ); પરાવલંબી સજીવો બીજાએ બનાવેલો ખોરાક લે છે (પ્રાણીઓ, ફૂગ)."),
     1: ("(b) नामांकन: बोमन संपुट (कप के आकार का), उसके अंदर केशिका गुच्छ (केशिकाओं का गुच्छ), नलिका, संग्राहक वाहिनी, और वृक्क धमनी की शाखा तथा वृक्क शिरा।", "(b) નામનિર્દેશ: બાઉમેનની કોથળી (પ્યાલા આકારની), તેની અંદર રુધિરકેશિકાગુચ્છ (કેશિકાઓનો ગુચ્છ), નલિકા, સંગ્રાહક નલિકા, અને મૂત્રપિંડ ધમનીની શાખા તથા મૂત્રપિંડ શિરા."),
     2: ("केशिका गुच्छ से बोमन संपुट में रुधिर का निस्यंदन होता है; नलिका में उपयोगी पदार्थ पुनः अवशोषित होते हैं।", "રુધિરકેશિકાગુચ્છમાંથી બાઉમેનની કોથળીમાં રુધિરનું ગાળણ થાય છે; નલિકામાં ઉપયોગી પદાર્થોનું પુનઃશોષણ થાય છે.")})

