mc("mcq06", ("कौन-सी रुधिर वाहिका विऑक्सीजनित रुधिर को हृदय से फुफ्फुसों तक ले जाती है?", "કઈ રુધિરવાહિની ઑક્સિજનરહિત રુધિરને હૃદયમાંથી ફેફસાં સુધી લઈ જાય છે?"), ("फुफ्फुस धमनी दाएँ निलय से निकलकर विऑक्सीजनित रुधिर को फुफ्फुसों तक ले जाती है।", "ફુપ્ફુસ ધમની જમણા ક્ષેપકમાંથી નીકળીને ઑક્સિજનરહિત રુધિરને ફેફસાં સુધી લઈ જાય છે."),
   {"Pulmonary artery": (("फुफ्फुस धमनी", "ફુપ્ફુસ ધમની"), OK), "Pulmonary vein": (("फुफ्फुस शिरा", "ફુપ્ફુસ શિરા"), ("यह फुफ्फुसों से ऑक्सीजनित रुधिर लाती है।", "તે ફેફસાંમાંથી ઑક્સિજનયુક્ત રુધિર લાવે છે.")),
    "Aorta": (("महाधमनी", "મહાધમની"), ("महाधमनी ऑक्सीजनित रुधिर शरीर में ले जाती है।", "મહાધમની ઑક્સિજનયુક્ત રુધિર શરીરમાં લઈ જાય છે.")), "Vena cava": (("महाशिरा", "મહાશિરા"), ("यह शरीर से विऑक्सीजनित रुधिर हृदय में लाती है।", "તે શરીરમાંથી ઑક્સિજનરહિત રુધિર હૃદયમાં લાવે છે."))})
mc("mcq07", ("मछली के हृदय में कितने कोष्ठ होते हैं?", "માછલીના હૃદયમાં કેટલા ખંડો હોય છે?"), ("मछली के हृदय में दो कोष्ठ होते हैं; प्रत्येक चक्र में रुधिर इससे केवल एक बार गुज़रता है।", "માછલીના હૃદયમાં બે ખંડો હોય છે; દરેક ચક્રમાં રુધિર તેમાંથી ફક્ત એક વાર પસાર થાય છે."),
   {"Two": (("दो", "બે"), OK), "Three": (("तीन", "ત્રણ"), ("उभयचरों और अनेक सरीसृपों में तीन कोष्ठ होते हैं।", "ઉભયજીવીઓ અને ઘણા સરીસૃપોમાં ત્રણ ખંડો હોય છે.")),
    "Four": (("चार", "ચાર"), ("पक्षियों और स्तनधारियों में चार कोष्ठ होते हैं।", "પક્ષીઓ અને સસ્તનોમાં ચાર ખંડો હોય છે.")), "One": (("एक", "એક"), ("किसी कशेरुकी का हृदय एक कोष्ठ का नहीं होता।", "કોઈ પૃષ્ઠવંશીનું હૃદય એક ખંડનું હોતું નથી."))})
mc("mcq08", ("दिन में ऊँचे पेड़ों में जल का ऊपर चढ़ना मुख्यतः किसके कारण होता है?", "દિવસે ઊંચાં વૃક્ષોમાં પાણીનું ઉપર ચડવું મુખ્યત્વે શાના કારણે થાય છે?"), ("पत्तियों से वाष्पन चूषण बनाता है जो जल को ऊपर खींचता है; मूल दाब रात में अधिक महत्वपूर्ण है।", "પર્ણોમાંથી બાષ્પીભવન ખેંચાણ સર્જે છે જે પાણીને ઉપર ખેંચે છે; મૂળદાબ રાત્રે વધુ મહત્ત્વનું છે."),
   {"transpiration pull": (("वाष्पोत्सर्जन खिंचाव", "બાષ્પોત્સર્જનનું ખેંચાણ"), OK), "root pressure": (("मूल दाब", "મૂળદાબ"), ("मूल दाब रात में मुख्य बल है।", "મૂળદાબ રાત્રે મુખ્ય બળ છે.")),
    "gravity": (("गुरुत्व", "ગુરુત્વ"), ("गुरुत्व जल को नीचे खींचता है, ऊपर नहीं।", "ગુરુત્વ પાણીને નીચે ખેંચે છે, ઉપર નહિ.")), "translocation": (("स्थानांतरण", "સ્થાનાંતરણ"), ("स्थानांतरण फ्लोएम में भोजन का वहन है।", "સ્થાનાંતરણ અન્નવાહકમાં ખોરાકનું વહન છે."))})
mc("mcq09", ("वृक्क की मूल निस्यंदन इकाई है:", "મૂત્રપિંડનો મૂળભૂત ગાળણ એકમ છે:"), ("प्रत्येक वृक्क में अनेक वृक्काणु होते हैं, जो रुधिर का निस्यंदन करते हैं।", "દરેક મૂત્રપિંડમાં ઘણા ઉત્સર્ગ એકમો હોય છે, જે રુધિરનું ગાળણ કરે છે."),
   {"nephron": (("वृक्काणु (नेफ्रॉन)", "ઉત્સર્ગ એકમ (નેફ્રૉન)"), OK), "neuron": (("न्यूरॉन", "ચેતાકોષ"), ("न्यूरॉन तंत्रिका कोशिका है।", "ચેતાકોષ એ ચેતાતંત્રનો કોષ છે.")),
    "alveolus": (("कूपिका", "વાયુકોષ્ઠ"), ("कूपिकाएँ फुफ्फुसों में होती हैं।", "વાયુકોષ્ઠો ફેફસાંમાં હોય છે.")), "villus": (("दीर्घरोम", "રસાંકુર"), ("दीर्घरोम क्षुद्रांत्र में होते हैं।", "રસાંકુરો નાના આંતરડામાં હોય છે."))})
mc("mcq10", ("जिस रोगी के वृक्क काम करना बंद कर चुके हैं, उसका उपचार किया जाता है:", "જે દર્દીના મૂત્રપિંડ કામ કરતા બંધ થઈ ગયા છે, તેની સારવાર થાય છે:"), ("कृत्रिम वृक्क अपोहन द्वारा रुधिर से नाइट्रोजनी अपशिष्ट हटाता है।", "કૃત્રિમ મૂત્રપિંડ ડાયાલિસિસ વડે રુધિરમાંથી નાઇટ્રોજનયુક્ત કચરો દૂર કરે છે."),
   {"dialysis": (("अपोहन (डायलिसिस) से", "ડાયાલિસિસથી"), OK), "transfusion": (("रुधिर आधान से", "રુધિર-આધાનથી"), ("आधान रुधिर बदलता है; यह अपशिष्ट नहीं हटाता।", "રુધિર-આધાન રુધિર આપે છે; તે કચરો દૂર કરતું નથી.")),
    "vaccination": (("टीकाकरण से", "રસીકરણથી"), ("टीकाकरण रोगों से बचाता है।", "રસીકરણ રોગોથી બચાવે છે.")), "photosynthesis": (("प्रकाशसंश्लेषण से", "પ્રકાશસંશ્લેષણથી"), ("प्रकाशसंश्लेषण पौधों में होता है।", "પ્રકાશસંશ્લેષણ વનસ્પતિમાં થાય છે."))})

# Written Shine
add("vsa1", ("प्रकाशसंश्लेषण के समय होने वाली तीन घटनाएँ कौन-सी हैं?", "પ્રકાશસંશ્લેષણ દરમિયાન થતી ત્રણ ઘટનાઓ કઈ છે?"),
    {0: ("(i) क्लोरोफ़िल प्रकाश ऊर्जा अवशोषित करता है। (ii) प्रकाश ऊर्जा रासायनिक ऊर्जा में बदलती है और जल हाइड्रोजन तथा ऑक्सीजन में अपघटित होता है।", "(i) હરિતદ્રવ્ય પ્રકાશ-ઊર્જાનું શોષણ કરે છે. (ii) પ્રકાશ-ઊર્જા રાસાયણિક ઊર્જામાં ફેરવાય છે અને પાણીનું હાઇડ્રોજન અને ઑક્સિજનમાં વિઘટન થાય છે."),
     1: ("(iii) कार्बन डाइऑक्साइड कार्बोहाइड्रेट में अपचयित होती है।", "(iii) કાર્બન ડાયૉક્સાઇડનું કાર્બોદિતમાં રિડક્શન થાય છે.")})
add("vsa2", ("लसीका के दो कार्य बताइए।", "લસિકાનાં બે કાર્યો જણાવો."),
    {0: ("यह आंत्र से पचे और अवशोषित वसा को ले जाती है।", "તે આંતરડામાંથી પચેલી અને શોષાયેલી ચરબી લઈ જાય છે."), 1: ("यह कोशिकाओं के बीच के स्थानों से अतिरिक्त तरल को वापस रुधिर में पहुँचाती है।", "તે કોષો વચ્ચેની જગ્યામાંથી વધારાનું પ્રવાહી પાછું રુધિરમાં પહોંચાડે છે.")})
add("sa1", ("प्रवाह-चित्र की सहायता से ग्लूकोज़ के विखंडन के तीन पथ दर्शाइए, और बताइए कि प्रत्येक कहाँ होता है।", "પ્રવાહ-આલેખની મદદથી ગ્લુકોઝના વિઘટનના ત્રણ માર્ગો દર્શાવો, અને દરેક ક્યાં થાય છે તે જણાવો."),
    {0: ("ग्लूकोज़ (6-कार्बन) कोशिकाद्रव्य में पाइरुवेट (3-कार्बन) और थोड़ी ऊर्जा में टूटता है।", "ગ્લુકોઝ (6-કાર્બન) કોષરસમાં પાયરુવેટ (3-કાર્બન) અને થોડી ઊર્જામાં તૂટે છે."),
     1: ("ऑक्सीजन के बिना (यीस्ट): पाइरुवेट से एथेनॉल, कार्बन डाइऑक्साइड और थोड़ी ऊर्जा। ऑक्सीजन की कमी (हमारी पेशी कोशिकाएँ): पाइरुवेट से लैक्टिक अम्ल और थोड़ी ऊर्जा।", "ઑક્સિજન વિના (યીસ્ટ): પાયરુવેટમાંથી ઇથેનૉલ, કાર્બન ડાયૉક્સાઇડ અને થોડી ઊર્જા. ઑક્સિજનની ઊણપ (આપણા સ્નાયુકોષો): પાયરુવેટમાંથી લેક્ટિક ઍસિડ અને થોડી ઊર્જા."),
     2: ("ऑक्सीजन के साथ (माइटोकॉन्ड्रिया): पाइरुवेट से कार्बन डाइऑक्साइड, जल और बहुत अधिक ऊर्जा।", "ઑક્સિજન સાથે (કણાભસૂત્ર): પાયરુવેટમાંથી કાર્બન ડાયૉક્સાઇડ, પાણી અને ઘણી વધુ ઊર્જા.")})
add("sa2", ("रंध्र कैसे खुलते और बंद होते हैं, इसका वर्णन कीजिए। रंध्रों के दो कार्य बताइए।", "વાયુરંધ્રો કેવી રીતે ખૂલે છે અને બંધ થાય છે તેનું વર્ણન કરો. વાયુરંધ્રનાં બે કાર્યો જણાવો."),
    {0: ("प्रत्येक रंध्र छिद्र दो द्वार कोशिकाओं से घिरा होता है। जल अंदर आने पर वे फूल जाती हैं और छिद्र खुलता है; जल खोने पर वे सिकुड़ जाती हैं और छिद्र बंद होता है।", "દરેક વાયુરંધ્ર બે રક્ષક કોષોથી ઘેરાયેલું હોય છે. પાણી અંદર આવતાં તે ફૂલે છે અને છિદ્ર ખૂલે છે; પાણી ગુમાવતાં તે સંકોચાય છે અને છિદ્ર બંધ થાય છે."),
     1: ("कार्य 1: प्रकाशसंश्लेषण के लिए गैसों का विनिमय (कार्बन डाइऑक्साइड अंदर, ऑक्सीजन बाहर)।", "કાર્ય 1: પ્રકાશસંશ્લેષણ માટે વાયુઓની આપ-લે (કાર્બન ડાયૉક્સાઇડ અંદર, ઑક્સિજન બહાર)."),
     2: ("कार्य 2: वाष्पोत्सर्जन द्वारा जल-वाष्प का निकलना, जो जल के ऊपर चढ़ने में सहायता करता है।", "કાર્ય 2: બાષ્પોત્સર્જન દ્વારા પાણીની વરાળ નીકળવી, જે પાણીને ઉપર ચડવામાં મદદ કરે છે.")})
add("la1", ("मनुष्य में मुँह से बृहदांत्र तक भोजन के पाचन के प्रक्रम का वर्णन कीजिए।", "મનુષ્યમાં મુખથી મોટા આંતરડા સુધી ખોરાકના પાચનની ક્રિયાનું વર્ણન કરો."),
    {0: ("मुँह: दाँत भोजन चबाते हैं; लार का लार एमिलेस मंड को शर्करा में तोड़ता है।", "મુખ: દાંત ખોરાક ચાવે છે; લાળનો લાળરસીય એમાયલેઝ સ્ટાર્ચને શર્કરામાં તોડે છે."),
     1: ("आमाशय: हाइड्रोक्लोरिक अम्ल माध्यम को अम्लीय बनाता है; पेप्सिन प्रोटीन पचाता है; श्लेष्मा अस्तर की रक्षा करता है।", "જઠર: હાઇડ્રોક્લોરિક ઍસિડ માધ્યમને ઍસિડિક બનાવે છે; પેપ્સિન પ્રોટીન પચાવે છે; શ્લેષ્મ દીવાલનું રક્ષણ કરે છે."),
     2: ("क्षुद्रांत्र: पित्त रस भोजन को क्षारीय बनाता है और वसा का इमल्सीकरण करता है; ट्रिप्सिन प्रोटीन और लाइपेज वसा पचाता है; आंत्र रस इन्हें अमीनो अम्ल, ग्लूकोज़, वसा-अम्ल और ग्लिसरॉल में बदलता है।",
         "નાનું આંતરડું: પિત્તરસ ખોરાકને આલ્કલાઇન બનાવે છે અને ચરબીનું તૈલોદીકરણ કરે છે; ટ્રિપ્સિન પ્રોટીન અને લાયપેઝ ચરબી પચાવે છે; આંત્રરસ તેમને એમિનો ઍસિડ, ગ્લુકોઝ, ફેટી ઍસિડ અને ગ્લિસરોલમાં ફેરવે છે."),
     3: ("क्षुद्रांत्र के दीर्घरोम पचे भोजन को रुधिर में अवशोषित करते हैं।", "નાના આંતરડાના રસાંકુરો પચેલા ખોરાકનું રુધિરમાં શોષણ કરે છે."), 4: ("बृहदांत्र: जल अवशोषित करती है; अपशिष्ट गुदा से निकाला जाता है।", "મોટું આંતરડું: પાણીનું શોષણ કરે છે; કચરો મળદ્વારથી બહાર કઢાય છે.")})
add("la2", ("मानव उत्सर्जन तंत्र का वर्णन कीजिए। वृक्काणु में मूत्र कैसे बनता है? अपोहन क्या है?", "માનવ ઉત્સર્જનતંત્રનું વર્ણન કરો. ઉત્સર્ગ એકમમાં મૂત્ર કેવી રીતે બને છે? ડાયાલિસિસ એટલે શું?"),
    {0: ("उत्सर्जन तंत्र में दो वृक्क, दो मूत्रवाहिनियाँ, एक मूत्राशय और एक मूत्रमार्ग होते हैं।", "ઉત્સર્જનતંત્રમાં બે મૂત્રપિંડ, બે મૂત્રવાહિનીઓ, એક મૂત્રાશય અને એક મૂત્રમાર્ગ હોય છે."),
     1: ("प्रत्येक वृक्काणु में केशिका गुच्छ से बोमन संपुट में रुधिर का निस्यंदन होता है।", "દરેક ઉત્સર્ગ એકમમાં રુધિરકેશિકાગુચ્છમાંથી બાઉમેનની કોથળીમાં રુધિરનું ગાળણ થાય છે."),
     2: ("नलिका में ग्लूकोज़, अमीनो अम्ल, लवण और जल की प्रमुख मात्रा पुनः अवशोषित होती है; शेष मूत्र है।", "નલિકામાં ગ્લુકોઝ, એમિનો ઍસિડ, ક્ષાર અને પાણીના મોટા ભાગનું પુનઃશોષણ થાય છે; બાકીનું મૂત્ર છે."),
     3: ("मूत्र मूत्रवाहिनियों से मूत्राशय में जाता है, जहाँ यह संचित रहता है, और मूत्रमार्ग से निकलता है।", "મૂત્ર મૂત્રવાહિનીઓ દ્વારા મૂત્રાશયમાં જાય છે, જ્યાં તે સંગ્રહાય છે, અને મૂત્રમાર્ગ દ્વારા બહાર નીકળે છે."),
     4: ("अपोहन: वृक्क के काम न करने पर कृत्रिम वृक्क रुधिर से नाइट्रोजनी अपशिष्ट हटाता है, जब रुधिर अपोहन द्रव में रखी नलियों से बहता है।", "ડાયાલિસિસ: મૂત્રપિંડ કામ ન કરે ત્યારે કૃત્રિમ મૂત્રપિંડ રુધિરમાંથી નાઇટ્રોજનયુક્ત કચરો દૂર કરે છે, જ્યારે રુધિર ડાયાલિસિસ પ્રવાહીમાં રાખેલી નળીઓમાંથી વહે છે.")})
add("cb1", ("विद्यालय की दौड़ में कबीर बहुत तेज़ दौड़ा और उसकी टाँगों में दर्दनाक क्रैम्प हो गए। उसके शिक्षक ने बताया कि उसकी पेशियों को पर्याप्त ऑक्सीजन नहीं मिल रही थी। इस बीच विद्यालय की रसोई में आटे में यीस्ट मिलाया गया, जो फूल गया और उसमें से हल्की ऐल्कोहॉल की गंध आई।\n\n"
            "(i) कबीर की टाँगों में क्रैम्प किस पदार्थ के कारण हुए? (1)\n\n(ii) आटा क्यों फूला? (1)\n\n(iii) पर्याप्त ऑक्सीजन होने पर कोशिका में पाइरुवेट कहाँ टूटता है, और उत्पाद क्या हैं? अथवा वायवीय श्वसन अवायवीय श्वसन से अधिक ऊर्जा क्यों मुक्त करता है? (2)",
            "શાળાની દોડમાં કબીર ખૂબ ઝડપથી દોડ્યો અને તેના પગના સ્નાયુઓ પીડાદાયક રીતે ખેંચાયા (ક્રૅમ્પ). તેના શિક્ષકે સમજાવ્યું કે તેના સ્નાયુઓને પૂરતો ઑક્સિજન મળતો ન હતો. એ દરમિયાન શાળાના રસોડામાં લોટમાં યીસ્ટ ઉમેરાયું, જે ફૂલ્યો અને તેમાંથી થોડી આલ્કોહૉલ જેવી ગંધ આવી.\n\n"
            "(i) કબીરના પગમાં ક્રૅમ્પ કયા પદાર્થને કારણે થયા? (1)\n\n(ii) લોટ કેમ ફૂલ્યો? (1)\n\n(iii) પૂરતો ઑક્સિજન હોય ત્યારે કોષમાં પાયરુવેટ ક્યાં તૂટે છે, અને નીપજો શી છે? અથવા જારક શ્વસન અજારક શ્વસન કરતાં વધુ ઊર્જા કેમ મુક્ત કરે છે? (2)"),
    {0: ("(i) लैक्टिक अम्ल, जो पेशी कोशिकाओं में ऑक्सीजन की कमी होने पर पाइरुवेट से बनता है।", "(i) લેક્ટિક ઍસિડ, જે સ્નાયુકોષોમાં ઑક્સિજનની ઊણપ હોય ત્યારે પાયરુવેટમાંથી બને છે."),
     1: ("(ii) यीस्ट अवायवीय श्वसन करता है और कार्बन डाइऑक्साइड छोड़ता है, जिससे आटा फूलता है।", "(ii) યીસ્ટ અજારક શ્વસન કરે છે અને કાર્બન ડાયૉક્સાઇડ છોડે છે, જેથી લોટ ફૂલે છે."),
     2: ("(iii) माइटोकॉन्ड्रिया में; उत्पाद कार्बन डाइऑक्साइड, जल और बहुत अधिक ऊर्जा हैं। अथवा वायवीय श्वसन में ग्लूकोज़ पूरी तरह कार्बन डाइऑक्साइड और जल में टूटता है; अवायवीय श्वसन में केवल आंशिक रूप से।",
         "(iii) કણાભસૂત્રમાં; નીપજો કાર્બન ડાયૉક્સાઇડ, પાણી અને ઘણી વધુ ઊર્જા છે. અથવા જારક શ્વસનમાં ગ્લુકોઝ સંપૂર્ણ રીતે કાર્બન ડાયૉક્સાઇડ અને પાણીમાં તૂટે છે; અજારક શ્વસનમાં ફક્ત આંશિક રીતે.")})
add("cb2", ("एक स्वास्थ्य शिविर में डॉक्टर ने मीरा के दादाजी का रक्तदाब 150/95 mm पारा मापा, और कक्षा को बताया कि सामान्य रक्तदाब लगभग 120/80 mm पारा होता है। उन्होंने यह भी समझाया कि हृदय में चार कोष्ठ होते हैं और रुधिर उससे दो बार गुज़रता है।\n\n"
            "(i) रक्तदाब मापने वाले यंत्र का नाम बताइए। (1)\n\n(ii) क्या दादाजी का रक्तदाब सामान्य है? (1)\n\n(iii) हृदय का कौन-सा भाग विऑक्सीजनित रुधिर लेता है, और उसे कहाँ भेजता है? अथवा शिराओं में वाल्व क्यों होते हैं? (2)",
            "એક આરોગ્ય શિબિરમાં ડૉક્ટરે મીરાના દાદાનું રુધિરદાબ 150/95 mm પારો માપ્યું, અને વર્ગને કહ્યું કે સામાન્ય રુધિરદાબ આશરે 120/80 mm પારો હોય છે. તેમણે એ પણ સમજાવ્યું કે હૃદયમાં ચાર ખંડો હોય છે અને રુધિર તેમાંથી બે વાર પસાર થાય છે.\n\n"
            "(i) રુધિરદાબ માપવાના સાધનનું નામ આપો. (1)\n\n(ii) શું દાદાનું રુધિરદાબ સામાન્ય છે? (1)\n\n(iii) હૃદયની કઈ બાજુ ઑક્સિજનરહિત રુધિર લે છે, અને તેને ક્યાં મોકલે છે? અથવા શિરાઓમાં વાલ્વ કેમ હોય છે? (2)"),
    {0: ("(i) स्फाइग्मोमैनोमीटर।", "(i) સ્ફિગ્મોમેનોમીટર."), 1: ("(ii) नहीं: यह सामान्य से अधिक है (उच्च रक्तदाब, अतिरुधिरदाब)।", "(ii) ના: તે સામાન્ય કરતાં વધુ છે (ઊંચું રુધિરદાબ, હાઇપરટેન્શન)."),
     2: ("(iii) दायाँ भाग: दायाँ अलिंद शरीर से विऑक्सीजनित रुधिर लेता है, और दायाँ निलय उसे फुफ्फुसों में पंप करता है। अथवा शिराओं में रुधिर कम दाब पर होता है; वाल्व सुनिश्चित करते हैं कि यह केवल हृदय की ओर बहे।",
         "(iii) જમણી બાજુ: જમણું કર્ણક શરીરમાંથી ઑક્સિજનરહિત રુધિર લે છે, અને જમણું ક્ષેપક તેને ફેફસાંમાં પંપ કરે છે. અથવા શિરાઓમાં રુધિર ઓછા દબાણે હોય છે; વાલ્વ ખાતરી કરે છે કે તે ફક્ત હૃદય તરફ વહે.")})

# Assertion-reason
_CORRECT = re.compile(r"^Correct! A is (?:true|false): (.*) R is (?:true|false): (.*)$")
def ar(key, a, r, wa, wr, ex):
    it = item(key)
    a_en, r_en = it["question"].replace("**Assertion (A):** ", "").split("\n\n**Reason (R):** ")
    wa_en, wr_en = _CORRECT.match(it["option_feedback"][it["correct_index"]]).groups()
    (a_hi, a_gu), (r_hi, r_gu) = fill(a_en, *a), fill(r_en, *r)
    (wa_hi, wa_gu), (wr_hi, wr_gu), (ex_hi, ex_gu) = fill(wa_en, *wa), fill(wr_en, *wr), fill(it["explanation"], *ex)
    return (a_hi, r_hi, a_gu, r_gu, wa_hi, wr_hi, wa_gu, wr_gu, ex_hi, ex_gu)
